@code {
    private BookAppointmentModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool submitted;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    private static readonly string[] Step1Fields =
        [nameof(BookAppointmentModel.PatientName), nameof(BookAppointmentModel.Email),
         nameof(BookAppointmentModel.Phone), nameof(BookAppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        customValidator?.ClearErrors();

        // Validate only step-1 fields
        var isValid = true;
        var store = new ValidationMessageStore(editContext);
        store.Clear();

        if (string.IsNullOrWhiteSpace(model.PatientName))
        {
            store.Add(editContext.Field(nameof(model.PatientName)), "Patient Name is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.Email))
        {
            store.Add(editContext.Field(nameof(model.Email)), "Email is required.");
            isValid = false;
        }
        else if (!IsValidEmail(model.Email))
        {
            store.Add(editContext.Field(nameof(model.Email)), "Invalid email format.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.Phone))
        {
            store.Add(editContext.Field(nameof(model.Phone)), "Phone is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.InsuranceProvider))
        {
            store.Add(editContext.Field(nameof(model.InsuranceProvider)), "Insurance Provider is required.");
            isValid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (isValid)
        {
            showStep2 = true;
            submitted = false;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        model.TimeSlot = "";
        availableSlots = [];

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        submitted = false;
        customValidator?.ClearErrors();
    }

    private async Task HandleSubmit()
    {
        customValidator?.ClearErrors();
        submitted = false;

        // Validate step-2 fields manually
        var store = new ValidationMessageStore(editContext);
        store.Clear();
        var isValid = true;

        if (string.IsNullOrWhiteSpace(model.Doctor))
        {
            store.Add(editContext.Field(nameof(model.Doctor)), "Preferred Doctor is required.");
            isValid = false;
        }
        if (!model.AppointmentDate.HasValue)
        {
            store.Add(editContext.Field(nameof(model.AppointmentDate)), "Date is required.");
            isValid = false;
        }
        else if (model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            store.Add(editContext.Field(nameof(model.AppointmentDate)), "Date must be in the future.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.TimeSlot))
        {
            store.Add(editContext.Field(nameof(model.TimeSlot)), "Time Slot is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.ReasonForVisit))
        {
            store.Add(editContext.Field(nameof(model.ReasonForVisit)), "Reason for Visit is required.");
            isValid = false;
        }
        else if (model.ReasonForVisit!.Length > 500)
        {
            store.Add(editContext.Field(nameof(model.ReasonForVisit)), "Reason must be 500 characters or less.");
            isValid = false;
        }

        editContext.NotifyValidationStateChanged();
        if (!isValid) return;

        // Server-side business-rule validation
        isSubmitting = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider, model.Doctor, model.TimeSlot);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private static bool IsValidEmail(string email)
    {
        var trimmed = email.AsSpan().Trim();
        int atIndex = trimmed.IndexOf('@');
        return atIndex > 0 && trimmed.LastIndexOf('.') > atIndex + 1 && trimmed[^1] != '.';
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_20e84761df5041eda97c64af7f410463.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, string> errors)
    {
        foreach (var (field, message) in errors)
        {
            messageStore!.Add(EditContext!.Field(field), message);
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

