@using sv_20e84761df5041eda97c64af7f410463.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    @* ── STEP 1: Patient Information ── *@
    <fieldset>
        <legend>Step 1 — Patient Information</legend>

        <div class="mb-3">
            <label class="form-label">Patient Name</label>
            <InputText class="form-control" @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <InputText class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Phone</label>
            <InputText class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label">Insurance Provider</label>
            <InputSelect class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ── STEP 2: Appointment Details ── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2 — Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label">Preferred Doctor</label>
                <InputSelect class="form-select" @bind-Value="model.Doctor" @bind:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label">Date</label>
                <InputDate class="form-control" @bind-Value="model.AppointmentDate" @bind:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label">Time Slot</label>
                <InputSelect class="form-select" @bind-Value="model.TimeSlot" disabled="@(availableSlots.Count == 0)">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label">Reason for Visit</label>
                <InputTextArea class="form-control" @bind-Value="model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
                Back
            </button>
            <button type="submit" class="btn btn-success" disabled="@isSubmitting">
                @(isSubmitting ? "Checking Availability..." : "Check Availability")
            </button>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private BookAppointmentModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool submitted;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    private static readonly string[] Step1Fields =
        [nameof(BookAppointmentModel.PatientName), nameof(BookAppointmentModel.Email),
         nameof(BookAppointmentModel.Phone), nameof(BookAppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        customValidator?.ClearErrors();

        // Validate only step-1 fields
        var isValid = true;
        var store = new ValidationMessageStore(editContext);
        store.Clear();

        if (string.IsNullOrWhiteSpace(model.PatientName))
        {
            store.Add(editContext.Field(nameof(model.PatientName)), "Patient Name is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.Email))
        {
            store.Add(editContext.Field(nameof(model.Email)), "Email is required.");
            isValid = false;
        }
        else if (!IsValidEmail(model.Email))
        {
            store.Add(editContext.Field(nameof(model.Email)), "Invalid email format.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.Phone))
        {
            store.Add(editContext.Field(nameof(model.Phone)), "Phone is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.InsuranceProvider))
        {
            store.Add(editContext.Field(nameof(model.InsuranceProvider)), "Insurance Provider is required.");
            isValid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (isValid)
        {
            showStep2 = true;
            submitted = false;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        model.TimeSlot = "";
        availableSlots = [];

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        submitted = false;
        customValidator?.ClearErrors();
    }

    private async Task HandleSubmit()
    {
        customValidator?.ClearErrors();
        submitted = false;

        // Validate step-2 fields manually
        var store = new ValidationMessageStore(editContext);
        store.Clear();
        var isValid = true;

        if (string.IsNullOrWhiteSpace(model.Doctor))
        {
            store.Add(editContext.Field(nameof(model.Doctor)), "Preferred Doctor is required.");
            isValid = false;
        }
        if (!model.AppointmentDate.HasValue)
        {
            store.Add(editContext.Field(nameof(model.AppointmentDate)), "Date is required.");
            isValid = false;
        }
        else if (model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            store.Add(editContext.Field(nameof(model.AppointmentDate)), "Date must be in the future.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.TimeSlot))
        {
            store.Add(editContext.Field(nameof(model.TimeSlot)), "Time Slot is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(model.ReasonForVisit))
        {
            store.Add(editContext.Field(nameof(model.ReasonForVisit)), "Reason for Visit is required.");
            isValid = false;
        }
        else if (model.ReasonForVisit!.Length > 500)
        {
            store.Add(editContext.Field(nameof(model.ReasonForVisit)), "Reason must be 500 characters or less.");
            isValid = false;
        }

        editContext.NotifyValidationStateChanged();
        if (!isValid) return;

        // Server-side business-rule validation
        isSubmitting = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider, model.Doctor, model.TimeSlot);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private static bool IsValidEmail(string email)
    {
        var trimmed = email.AsSpan().Trim();
        int atIndex = trimmed.IndexOf('@');
        return atIndex > 0 && trimmed.LastIndexOf('.') > atIndex + 1 && trimmed[^1] != '.';
    }
}
"}

